def nearest_match(I,O,hr0,hr1,hc0,hc1):
    h,w=hr1-hr0+1,hc1-hc0+1
    tgt=O[hr0:hr1+1,hc0:hc1+1]
    res=[]
    for sgh,sww in [(h,w),(w,h)]:
        for tr,name in [('id','id'),('F','F'),('U','U'),('B180','B180'),('r90','r90'),('r270','r270'),('TF','flror90'),('TU','flipudrot')]:
            if name=='TF': V=lambda B:np.fliplr(np.rot90(B))
            elif name=='TU': V=lambda B:np.flipud(np.rot90(B))
            else:
                import functools; V={'id':lambda x:x,'F':np.fliplr,'U':np.flipud,'B180':lambda x:x[::-1,::-1],'r90':np.rot90,'r270':lambda x:np.rot90(x,-1)}.get(name,lambda x:x)(x)
            for dr in range(I.shape[0]-sgh+1):
                for dc_ in range(I.shape[1]-sww+1):
                    src=I[dr:dr+sgh,dc_:dc_+sww]
                    if (src==6).any(): continue
                    Vv=V(src)
                    if np.array_equal(Vv,tgt):
                        d=abs(dr-hr0)+abs(dc_-hc0)
                        res.append((d,name,sgh,sww,dr,dc_,src.copy()))
    return min(res,key=lambda t:t[0])
