def solve(I):
    I=np.array(I); H,W=I.shape
    lab,n=ndimage.label(I==6)
    OUT=I.copy()
    for k in range(1,n+1):
        a,b=np.where(lab==k)
        r0,r1,c0,c1=int(a.min()),int(a.max()),int(b.min()),int(b.max())
        h,w=r1-r0+1,c1-c0+1
        tgt=I[r0:r1+1,c0:c1+1]
        cands=[]
        for sgh,sww in [(h,w),(w,h)]:
            for nm,tr in TRANS.items():
                for dr in range(H-sgh+1):
                    for dc_ in range(W-sww+1):
                        src=I[dr:dr+sgh,dc_:dc_+sww]
                        if (src==6).any(): continue
                        if np.array_equal(tr(src),tgt):
                            d=abs(dr-r0)+abs(dc_-c0)
                            cands.append((d,nm,sgh,sww,dr,dc_,tr(src)))
        cands.sort(key=lambda t:t[0])
        _,tn,sgh,sww,dr,dc_,V=cands[0]
        OUT[r0:r1+1,c0:c1+1]=V
    return OUT
